#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-09-29
/**
 * skill-preapproval-inventory.mjs: which ork skills lean on `allowed-tools`
 * pre-approval, written into the doctor reference so the list cannot drift.
 *
 * WHY (#4542). `allowed-tools` pre-grants the listed tools while the skill runs
 * (see the header of scripts/allowed-tools-check.mjs for the doc quote). Two
 * upstream fixes take that pre-grant away under managed
 * `allowManagedPermissionRulesOnly`:
 *
 *   2.1.282 "Fixed repository, user and `--add-dir` skills, commands and
 *           skills-directory plugin manifests pre-approving their own tools via
 *           `allowed-tools` under managed `allowManagedPermissionRulesOnly`"
 *   2.1.284 "Fixed plugins from marketplaces, claude.ai and npm pre-approving
 *           their own tools via `allowed-tools` under managed
 *           `allowManagedPermissionRulesOnly`; only plugins from an official
 *           Anthropic source or a source that managed settings vouch for keep
 *           that pre-approval"
 *
 * ork installs from a marketplace, so in an org that sets that key every
 * prompt-gated tool below prompts again (or is denied in a context that cannot
 * prompt). Outside such orgs nothing changed, which is why the fix is a
 * documented inventory and not a frontmatter edit.
 *
 * PROMPT_GATED is the "Permission required: Yes" column of
 * https://code.claude.com/docs/en/tools-reference.md (read 2026-09-29).
 * `mcp__*` tools are counted too: the table does not list them, but an MCP tool
 * with no allow rule prompts. A tool the table marks No (Read, Grep, Glob,
 * Task*, Agent, SendMessage, ToolSearch, Cron*, ExitWorktree, ...) never needed
 * the pre-grant, so a skill listing only those is unaffected.
 *
 * Usage:
 *   node scripts/skill-preapproval-inventory.mjs           # --check (default)
 *   node scripts/skill-preapproval-inventory.mjs --write   # regenerate the table
 */
import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SKILLS_ROOT = join(REPO_ROOT, 'src', 'skills');
const REFERENCE = join(SKILLS_ROOT, 'doctor', 'references', 'skill-preapproval.md');
const BEGIN = '<!-- skill-preapproval:begin (generated by scripts/skill-preapproval-inventory.mjs --write) -->';
const END = '<!-- skill-preapproval:end -->';

export const PROMPT_GATED = new Set([
  'Artifact', 'Bash', 'Edit', 'EnterWorktree', 'ExitPlanMode', 'Monitor',
  'NotebookEdit', 'PowerShell', 'ShareOnboardingGuide', 'Skill', 'WebFetch',
  'WebSearch', 'Workflow', 'Write',
]);

/** The bare tool name of an allowed-tools entry: `Bash(git:*)` -> `Bash`. */
export function toolName(entry) {
  return entry.replace(/\(.*$/, '').trim();
}

export function isPromptGated(entry) {
  const name = toolName(entry);
  return PROMPT_GATED.has(name) || name.startsWith('mcp__');
}

// Same reader as scripts/allowed-tools-check.mjs (which runs its gate on
// import, so it cannot be imported): one scalar-or-list field, no YAML dep.
export function parseAllowedTools(text) {
  const m = /^---\r?\n([\s\S]*?)\r?\n---/.exec(text);
  if (!m) return null;
  const body = m[1];
  const inline = /^allowed-tools:[ \t]*(.+)$/m.exec(body);
  if (inline) {
    // Inline list `[A, B]` or the normalised string `"A B"`: split on commas
    // and on whitespace outside parentheses, so `Bash(npm run x)` stays whole.
    return inline[1]
      .trim()
      .replace(/^\[|\]$/g, '')
      .replace(/^["']|["']$/g, '')
      .split(/,\s*|\s+(?![^()]*\))/)
      .map((s) => s.trim().replace(/^["']|["']$/g, ''))
      .filter(Boolean);
  }
  const block = /^allowed-tools:[ \t]*\r?\n((?:[ \t]*-[ \t]*\S+\r?\n?)+)/m.exec(body);
  if (block) {
    return block[1]
      .split(/\r?\n/)
      .map((l) => l.replace(/^[ \t]*-[ \t]*/, '').trim())
      .filter(Boolean);
  }
  return null;
}

export function inventory() {
  const rows = [];
  for (const name of readdirSync(SKILLS_ROOT).sort()) {
    const file = join(SKILLS_ROOT, name, 'SKILL.md');
    if (!existsSync(file)) continue;
    const tools = parseAllowedTools(readFileSync(file, 'utf8')) ?? [];
    const gated = tools.filter(isPromptGated);
    rows.push({ name, total: tools.length, gated });
  }
  return rows;
}

export function renderTable(rows) {
  const affected = rows.filter((r) => r.gated.length > 0);
  const unaffected = rows.length - affected.length;
  const lines = [
    BEGIN,
    '',
    `${affected.length} of ${rows.length} skills pre-grant at least one prompt-gated tool; ` +
      `${unaffected} list none (or no \`allowed-tools\` at all) and are unaffected.`,
    '',
    '| Skill | Prompt-gated tools it pre-grants |',
    '|---|---|',
    ...affected.map((r) => `| \`${r.name}\` | ${r.gated.map((t) => `\`${t}\``).join(', ')} |`),
    '',
    END,
  ];
  return lines.join('\n');
}

function spliceInto(doc, table) {
  const a = doc.indexOf(BEGIN);
  const b = doc.indexOf(END);
  if (a === -1 || b === -1 || b < a) {
    throw new Error(`markers missing in ${REFERENCE}`);
  }
  return doc.slice(0, a) + table + doc.slice(b + END.length);
}

const invokedDirectly = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (invokedDirectly) {
  const write = process.argv.includes('--write');
  const doc = readFileSync(REFERENCE, 'utf8');
  const next = spliceInto(doc, renderTable(inventory()));
  if (write) {
    writeFileSync(REFERENCE, next);
    console.log(`wrote ${REFERENCE}`);
  } else if (next !== doc) {
    console.error(
      'DRIFT: the skill pre-approval table in src/skills/doctor/references/skill-preapproval.md ' +
        'no longer matches the skills. Run: node scripts/skill-preapproval-inventory.mjs --write',
    );
    process.exit(1);
  } else {
    console.log('skill pre-approval inventory: in sync');
  }
}
